"""Japanese prose for the first Surf Japan glossary articles."""

ARTICLES = {
    "surf": {"standfirst": "サーフとは、海を渡るエネルギーそのものではなく、海岸がそれを乗れる砕波へ変える瞬間です。", "sections": [("サーフが始まる場所", "うねりは、乗るものを何も作らないまま深い海を何日も進めます。浅い水深へ入ると、海底が波の下部を遅らせ、フェイスを急にし、最後には波頂を前へ倒します。岸へ向かって進むその砕けた波がサーフです。"), ("区別する理由", "予報は通常、沖合のうねりを表し、サーフレポートは特定のスポットで割れる波を表します。両者はつながっていますが、サンドバー、潮、風、海岸線によって、同じうねりがある浜ではクリーンなサーフになり、数キロ先では弱いクローズアウトになることがあります。")]},
    "swell": {"standfirst": "うねりは、それを作った風が去ったあとも進み続ける、まとまりのある波のエネルギーです。", "sections": [("地域の乱れではなく旅人", "風はまず海を乱します。波が低気圧の場所を離れると、より長く規則的なエネルギーが広い間隔のラインへ整理されます。そのラインは海を横断し、地元が無風でもうねりとして海岸へ届きます。"), ("うねりの読み方", "波高は沖合の波の大きさ、周期はエネルギーの間隔、方向はどの海岸や岬が受け取れるかを示します。特定のビーチで何が起きるかを決める前に、この三つを一緒に読みます。")]},
    "groundswell": {"standfirst": "グラウンドスウェルは遠くの低気圧が作る長周期のうねりで、近くの風波よりクリーンで規則的、かつ力強いことが多い波です。", "sections": [("距離が時間を与える", "遠い低気圧には、波を育てるための広い海面と時間があります。移動中に短く乱れた波から先に消え、岸にはたいてい長い周期をもつ整ったパルスが届きます。"), ("海岸では", "長周期のエネルギーは沖合から海底を感じ、岬を回り込んで守られた湾へ入ることがあります。また、同じ高さでも想像するより沖で、より強く、いつものサンドバーを割れさせることがあります。")]},
    "wind-swell": {"standfirst": "ウインドスウェルは近くで生まれる短周期の波です。見つけやすい一方で変わりやすく、地元の天気に強く左右されます。", "sections": [("近くで生まれる", "風が近い海面を吹くと、エネルギーを直接水面へ渡します。フェッチが短い、または風が数時間しか吹かなければ、波は間隔が狭く不規則なままです。"), ("予想できること", "ウインドスウェルでも、とくに開けたビーチブレイクでは楽しいサーフになります。グラウンドスウェルより整う時間が短いため、地元の風は重要です。弱いオフショアは面を整え、オンショアはすぐにチョップへ変えます。")]},
    "fetch": {"standfirst": "フェッチは、波を作る間に風が吹く開けた水面の距離です。", "sections": [("風の助走路", "十分な風速と時間があれば、長いフェッチは風が海をより長く押すことを可能にします。一般に、より大きく長周期の波が育ちます。短いフェッチでは、風が陸に当たるか向きを変えるまでに作れるエネルギーが限られます。"), ("物語の一部", "フェッチだけで決まるわけではありません。風の強さ、続く時間、向きの安定も重要です。これらは、ある低気圧が小さな地元の風波しか作らず、別の低気圧が太平洋を横断するグラウンドスウェルを送る理由を説明します。")]},
    "wave-period": {"standfirst": "波周期は波頂から次の波頂までの秒数です。高さだけよりも、うねりの感じ方を素早く教えてくれます。", "sections": [("間隔が情報を運ぶ", "6秒の波列は波頂の間隔が狭く、地元の風波と結びつくことが多いです。14秒の波列は間隔が大きく、通常は遠くから来ます。長い周期はエネルギーをより深く運び、より沖から海岸と関わります。"), ("波高より先に見る", "同じ波高を示す二つの予報が、まったく異なるサーフを作ることがあります。長周期のうねりはより強く入り、岬を回り、より沖で立ち上がります。波高は予報の一部で、周期がその文脈を与えます。")]},
    "swell-direction": {"standfirst": "うねりの向きは、うねりがどの方角から来るかです。海岸が開いているか、守られているか、屈折した端だけを受けるかを決めます。", "sections": [("スポットにはウィンドウがある", "どのスポットも、開けた海の限られた弧に面しています。東に開くビーチは東うねりを直接受けても、西からのうねりは逃すかもしれません。岬、島、湾はそのウィンドウをさらに狭めたり曲げたりします。"), ("向きが形を変える", "入射角は、エネルギーがサンドバーやリーフのどこへ先に届くかも変えます。方向の小さな変化でピークが動き、ブレイクの片側が良くなったり、期待した波がクローズアウトになったりします。")]},
    "set": {"standfirst": "セットは近い間隔で続けて入る波のまとまりで、間の波より大きいことがよくあります。", "sections": [("波が群れで来る理由", "うねりは、重なり合う多くの波列からできています。ある瞬間には波頂がそろって強め合い、別の瞬間には部分的に打ち消します。ブレイクでは、大きな波のパルスのあとに静かな間が来るように見えます。"), ("セットの使い方", "沖へ出る前に数サイクルを観察します。セットは本当のアウトサイドピーク、チャンネルが安全でなくなるとき、次の白波までの時間を見せます。小さな波をすべて追うより、良いセットを待つ方が良いことが多いです。")]},
    "lull": {"standfirst": "セット間の静かな時間は、ラインナップへ出るのに役立ちますが、海が穏やかになったという約束ではありません。", "sections": [("パルスの切れ目", "波の群れの間は、同時に来る波頂が少なく、ブレイクがだまされるほど穏やかに見えることがあります。この間は天気の変化ではなく、セットを作る同じ重なった波のエネルギーから生まれます。"), ("時機を選ぶ", "この間はインパクトゾーンを通る、または位置を戻す最良の時間になることがあります。ただし沖を見続けます。次のセットはすでに水平線に見えているかもしれず、最大の波は最も長い待ち時間のあとに来ることがあります。")]},
}
